// SPDX-License-Identifier: GPL-3.0-only
// EXTERNAL composite certificate vectors — artifacts produced by OTHER
// implementations, vendored from the IETF Hackathon pqc-certificates repo
// (round r5): https://github.com/IETF-Hackathon/pqc-certificates
//
// WHY THIS FILE EXISTS
// -------------------
// On 2026-08-17 the classical half of every composite certificate this project
// produced was signed with the wrong hash (SHA-512 instead of the profile's
// §6 "Traditional Signature Algorithm"). The bug was invisible to the entire
// test suite because our signer, our verifier AND the KMIP cross-engine test
// were all written from the same misreading of the draft. Round-trips passed;
// the certificates were non-interoperable with every conformant implementation.
//
// No in-house test could ever have caught that. Only an artifact produced by
// someone else could — and did. These vectors are that guard. Do not replace
// them with locally generated certificates: a self-produced vector re-creates
// exactly the blind spot this file exists to close.
//
// Refresh policy: bump to a newer Hackathon round deliberately, and re-run the
// tests. A vector that starts failing after a code change is the signal this
// file is for — investigate the change, do not "fix" the vector.
export interface ExternalCompositeVector {
  id: string
  /** Composite signatureAlgorithm OID */
  oid: string
  /** Producing implementation — the point is that it is NOT us */
  producer: string
  /** Why this particular profile earns a slot */
  rationale: string
  /**
   * 'valid'                 - both halves MUST verify.
   * 'classical-unsupported' - classical algorithm not implementable here;
   *                           MUST report not-checkable (null) and fail closed.
   */
  expect: 'valid' | 'classical-unsupported'
  /** Self-signed trust anchor, DER, base64 */
  derBase64: string
}

