/**
 * NORMATIVE raw-signature vectors from the composite-sigs draft's own
 * `src/testvectors.json` (lamps-wg/draft-composite-sigs) — the vectors the
 * specification publishes, produced by the reference implementation that lives
 * beside the draft source.
 *
 * These are the STRONGEST guard in this project. They involve no certificate
 * encoding at all: a public key, a signature, and a fixed message. If our
 * composite construction is right — M' layout, prefix, label, pre-hash, FIPS
 * 204 context, ML-DSA-first split, and the §6 traditional hash — these verify.
 * If any one of those is wrong, they do not.
 *
 * All three verified on 2026-08-18 with tradHash = SHA-256 (P-256) / SHA-384
 * (P-384), confirming the F17 fix against the specification's own output.
 *
 * NOTE: the draft's `x5c` CERTIFICATE vectors do NOT currently verify their
 * classical half, while these raw vectors from the same file do. That isolates
 * the discrepancy to certificate encoding in the generator, not the signature
 * scheme. Do not "fix" our verifier to accommodate those certificates.
 */
export interface DraftRawVector {
  tcId: string
  /** composite OID this vector's profile maps to */
  oid: string
  /**
   * 'verifies'              - both halves MUST verify. Pins the F17 fix.
   * All four verify. `.49` is deliberately retained as a HIGH-S regression
   * case: its ECDSA signature has a high S value, which @noble rejects under
   * its default low-S enforcement. That default silently rejected ~50% of
   * valid third-party certificates until 2026-08-18. Do not remove this vector.
   */
  expect: 'verifies'
  note: string
  /** composite public key: mldsaPK || tradPK, base64 */
  pkBase64: string
  /** composite signature over DRAFT_VECTOR_MESSAGE with empty ctx, base64 */
  sigBase64: string
}

/** The fixed message the draft generator signs (generate_test_vectors.py). */
export const DRAFT_VECTOR_MESSAGE = 'The quick brown fox jumps over the lazy dog.'

